async (page) => {
  const checks = [];
  const check = (value, name) => { if (!value) throw new Error(name); checks.push(name); };
  const go = async query => { await page.evaluate(()=>window.__qaUnload?.forEach(fn=>window.removeEventListener('beforeunload',fn))); await page.goto('http://127.0.0.1:4175/?' + query); await page.locator('h1:visible').waitFor(); };
  await page.setViewportSize({width:390,height:844});
  await go('page=members');
  await page.getByRole('searchbox',{name:'Search members'}).fill('Morgan');
  check(await page.locator('.member-row:visible').count()===2,'Search finds both matching names');
  await page.getByRole('link',{name:'Marks',exact:true}).click();
  await page.getByRole('link',{name:'Members',exact:true}).click();
  check(await page.getByRole('searchbox').inputValue()==='Morgan','Tab switch preserves search');
  await page.goBack();check((await page.locator('h1:visible').innerText())==='Weekly marks','Browser Back restores prior tab');
  await page.goForward();
  await page.getByRole('button',{name:'Reset filters',exact:true}).click();
  await page.getByRole('button',{name:'Filter members',exact:true}).click();
  await page.getByRole('group',{name:'Filter by squad'}).getByRole('button',{name:'2',exact:true}).click();
  check(await page.evaluate(()=>document.activeElement?.textContent)==='2','Filter changes preserve focus');
  await page.keyboard.press('Tab');
  check(await page.evaluate(()=>!!document.activeElement?.closest('dialog')),'Dialog contains keyboard focus');
  await page.keyboard.press('Escape');
  check(await page.getByRole('button',{name:/Filter members/}).evaluate(e=>e===document.activeElement),'Escape closes and restores trigger focus');
  check(await page.locator('.member-row:visible').count()===6,'Squad filter shows six members');
  await page.getByRole('button',{name:'Reset filters',exact:true}).click();
  await page.getByRole('button',{name:'Add member',exact:true}).click();
  await page.getByRole('textbox',{name:'Name',exact:true}).fill('Jamie Example');
  await page.getByRole('dialog').getByRole('button',{name:'Add member',exact:true}).click();
  check(await page.locator('.member-row:visible').count()===19,'Add member updates only local roster');
  await page.getByRole('button',{name:/View Jamie Example/}).click();
  await page.getByRole('button',{name:'Edit',exact:true}).click();
  await page.getByRole('textbox',{name:'Name',exact:true}).fill('Jamie Updated');
  await page.getByRole('button',{name:'Save changes',exact:true}).click();
  check(await page.getByRole('button',{name:/View Jamie Updated/}).count()===1,'Edit member updates local roster');
  await go('page=members');
  await page.getByRole('button',{name:/View Alex Morgan/}).click();
  await page.getByRole('button',{name:'Review Friday 9 October score',exact:true}).click();
  check(await page.getByRole('button',{name:'Unlock',exact:true}).count()===1,'History review opens the locked dated marks task');
  await page.getByRole('button',{name:'Unlock',exact:true}).click();
  check(await page.getByRole('textbox',{name:'Score for Alex Morgan',exact:true}).isEnabled(),'Explicit Unlock enables past-meeting correction');
  await go('page=marks');
  await page.getByRole('textbox',{name:'Score for Alex Morgan',exact:true}).fill('11');
  await page.getByRole('group',{name:'Marks squad',exact:true}).getByRole('button',{name:'2',exact:true}).click();
  await page.getByRole('button',{name:'Save marks',exact:true}).click();
  await page.getByRole('textbox',{name:'Score for Alex Morgan',exact:true}).waitFor();
  check(await page.getByRole('textbox',{name:'Score for Alex Morgan',exact:true}).evaluate(e=>e===document.activeElement),'Save reveals and focuses an invalid score outside the selected squad');
  await go('page=marks');
  await page.getByRole('textbox',{name:'Score for Alex Morgan',exact:true}).fill('.5');
  check(await page.getByRole('textbox',{name:'Score for Alex Morgan',exact:true}).getAttribute('aria-invalid')==='false','Leading-decimal Company score remains valid');
  await page.getByRole('textbox',{name:'Score for Alex Morgan',exact:true}).press('Enter');
  check(await page.getByRole('textbox',{name:'Score for Charlie Wilson',exact:true}).evaluate(e=>e===document.activeElement),'Enter advances to next enabled score');
  await page.getByRole('button',{name:'Present for Leo Thompson',exact:true}).click();
  check(await page.evaluate(()=>window.__qaUnload.length>0),'Dirty marks register browser unload protection');
  check(await page.getByRole('textbox',{name:'Score for Leo Thompson',exact:true}).isEnabled(),'Present enables numeric score');
  await page.getByRole('textbox',{name:'Score for Leo Thompson',exact:true}).fill('11');
  check(await page.getByRole('textbox',{name:'Score for Leo Thompson',exact:true}).getAttribute('aria-invalid')==='true','Out-of-range score has linked invalid state');
  await page.getByRole('textbox',{name:'Score for Leo Thompson',exact:true}).fill('');
  await page.getByRole('button',{name:'Previous meeting',exact:true}).click();
  check(await page.getByRole('dialog',{name:'Keep your changes?'}).count()===1,'Date switch protects unsaved marks');
  await page.getByRole('button',{name:'Stay here',exact:true}).click();
  await page.getByRole('button',{name:/Switch workspace/}).click();
  await page.getByRole('button',{name:/Company Section School years/}).click();
  check(await page.getByRole('button',{name:'Save marks',exact:true}).count()===1,'Selecting current workspace preserves draft');
  await page.getByRole('button',{name:'Save marks',exact:true}).click();
  await page.getByRole('button',{name:'Saved',exact:true}).waitFor();
  check(await page.getByRole('textbox',{name:'Score for Leo Thompson',exact:true}).inputValue()==='0','Present blank score saves as zero');
  await page.getByRole('button',{name:'Absent for Leo Thompson',exact:true}).click();
  check(await page.getByRole('textbox',{name:'Score for Leo Thompson',exact:true}).isDisabled(),'Absent disables score');
  await page.getByRole('button',{name:'Not recorded for Leo Thompson',exact:true}).click();
  check(await page.getByRole('button',{name:'Not recorded for Leo Thompson',exact:true}).getAttribute('aria-pressed')==='true','Attendance has explicit unrecorded state');
  await go('page=marks&section=junior');
  await page.getByRole('textbox',{name:'Behaviour score for Alex Morgan',exact:true}).fill('5.01');
  check(await page.getByRole('textbox',{name:'Behaviour score for Alex Morgan',exact:true}).getAttribute('aria-invalid')==='true','Junior behaviour maximum remains five');
  await page.getByRole('textbox',{name:'Behaviour score for Alex Morgan',exact:true}).fill('4.25');
  check(await page.getByRole('textbox',{name:'Behaviour score for Alex Morgan',exact:true}).getAttribute('aria-invalid')==='false','Junior accepts two decimal places');
  check(await page.getByRole('button',{name:'Calendar & events',exact:true}).count()===0,'Junior has no Company calendar entry');
  await go('page=marks&simulate=offline');
  await page.getByRole('textbox',{name:'Score for Alex Morgan',exact:true}).fill('9.5');
  await page.getByRole('button',{name:'Save marks',exact:true}).click();
  await page.getByRole('button',{name:'Try again',exact:true}).waitFor();
  check(await page.getByRole('textbox',{name:'Score for Alex Morgan',exact:true}).inputValue()==='9.5','Failed save retains draft');
  await page.getByRole('button',{name:'Reconnect',exact:true}).click();
  await page.getByRole('button',{name:'Try again',exact:true}).click();
  await page.getByRole('button',{name:'Saved',exact:true}).waitFor();checks.push('Retry recovers simulated failed save');
  await go('page=squad&role=leader');
  check(await page.locator('.report-member:visible').count()===6,'Leader sees six own-squad member rows');
  check(await page.locator('.report-member').filter({hasText:'James Taylor'}).count()===0,'Leader report excludes other squads’ members');
  await page.getByRole('button',{name:/Select week:.*25 Sept/}).click();
  check(await page.getByRole('combobox',{name:'Report meeting'}).inputValue()==='4','Chart selection updates dated report');
  await page.getByRole('button',{name:'Recent 5',exact:true}).click();
  await page.getByRole('button',{name:'All 8 meetings',exact:true}).click();
  check(await page.locator('.chart-column:visible').count()===8,'All meetings remain available in chart');
  await go('page=squad&role=boy');
  check((await page.locator('h1:visible').innerText())==='Hi, Alex','Ordinary boy cannot navigate to squad report');
  check(await page.locator('.report-member').count()===0,'Ordinary portal contains no teammate report');
  await go('page=members');
  await page.getByRole('link',{name:'Marks',exact:true}).click();
  await page.getByRole('link',{name:'Members',exact:true}).click();
  await page.getByRole('button',{name:'Filter members',exact:true}).click();
  await page.goBack();
  check(await page.getByRole('dialog').count()===0 && await page.evaluate(()=>document.body.style.overflow)!=='hidden','Browser Back closes sheet and unlocks page scrolling');
  await go('page=more');
  await page.getByRole('switch',{name:'Reduce motion',exact:true}).click();
  check(await page.locator('.prototype-app').evaluate(e=>e.classList.contains('reduce-motion')),'Reduce motion preference affects application');
  await page.getByRole('switch',{name:'Solid navigation',exact:true}).click();
  check(await page.locator('.tabbar').evaluate(e=>getComputedStyle(e).backdropFilter)==='none','Solid navigation removes backdrop filter');
  await page.emulateMedia({reducedMotion:'reduce'});
  check(await page.locator('.screen:visible').evaluate(e=>getComputedStyle(e).animationName)==='none','System reduced-motion overrides screen animation');
  await page.emulateMedia({reducedMotion:'no-preference'});
  return {passed:checks.length,checks,scope:'Synthetic isolated prototype. Chromium automation, not iOS device certification.'};
}
